package com.bank.flink.late;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// Reproduces Flink's late-data handling: on-time accept, allowed-lateness
// recomputation, and side-output for events later than the grace period.
class LateAwareWindowEngine {
    private static final Logger log = Logger.getLogger(LateAwareWindowEngine.class.getName());

    private final long windowSize;
    private final long outOfOrderness;
    private final long allowedLateness;
    private long maxSeen = Long.MIN_VALUE;

    // window state: key = accountId|windowStart -> running total
    private final Map<String, BigDecimal> windows = new HashMap<>();
    // windows already purged (past end + lateness)
    private final Map<String, Boolean> purged = new HashMap<>();
    // side output for events too late even for the grace period
    private final List<Txn> lateSideOutput = new ArrayList<>();

    LateAwareWindowEngine(long windowSize, long outOfOrderness, long allowedLateness) {
        this.windowSize = windowSize;
        this.outOfOrderness = outOfOrderness;
        this.allowedLateness = allowedLateness;
    }

    private long windowStart(long ts) { return ts - (ts % windowSize); }
    private long watermark() { return maxSeen == Long.MIN_VALUE ? Long.MIN_VALUE : maxSeen - outOfOrderness; }

    void process(Txn txn) {
        if (txn.getEventTimeMillis() > maxSeen) maxSeen = txn.getEventTimeMillis();
        long start = windowStart(txn.getEventTimeMillis());
        long end = start + windowSize;
        String key = txn.getAccountId() + "|" + start;
        long wm = watermark();

        if (wm < end) {
            // ON TIME: watermark has not passed window end yet.
            windows.merge(key, txn.getAmount(), BigDecimal::add);
            log.info(() -> "ON-TIME " + key + " total now " + windows.get(key));
        } else if (wm < end + allowedLateness && !Boolean.TRUE.equals(purged.get(key))) {
            // LATE BUT WITHIN GRACE: reopen window, recompute, re-emit.
            windows.merge(key, txn.getAmount(), BigDecimal::add);
            log.warning(() -> "LATE-RECOMPUTE " + key + " updated total " + windows.get(key));
        } else {
            // TOO LATE: route to side output for reconciliation.
            lateSideOutput.add(txn);
            log.severe(() -> "TOO-LATE " + key + " amount " + txn.getAmount() + " -> side output");
        }

        // purge windows whose end + lateness the watermark has passed
        purgeExpired(wm);
    }

    private void purgeExpired(long wm) {
        for (String key : new ArrayList<>(windows.keySet())) {
            long start = Long.parseLong(key.split("\\|")[1]);
            if (wm >= start + windowSize + allowedLateness) {
                purged.put(key, true);
            }
        }
    }

    Map<String, BigDecimal> getWindows() { return windows; }
    List<Txn> getLateSideOutput() { return lateSideOutput; }
}
