package com.bank.flink.late;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: on-time, slightly-late (recompute), and very-late (side output).
public class LateEventsDemo {
    private static final Logger log = Logger.getLogger(LateEventsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new LateLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // window 60s, out-of-orderness 5s, allowed lateness 120s
        LateAwareWindowEngine engine = new LateAwareWindowEngine(60_000L, 5_000L, 120_000L);

        // 1) On-time transaction in the 10:00 window.
        engine.process(new Txn("SAV2001", new BigDecimal("1000.00"), 10_000));
        // 2) Advance watermark well past the 10:00 window end.
        engine.process(new Txn("CUR3001", new BigDecimal("500.00"), 120_000));
        // 3) Slightly-late txn for the 10:00 window (within 120s grace) -> recompute.
        engine.process(new Txn("SAV2001", new BigDecimal("250.00"), 30_000));
        // 4) Push watermark far into the future.
        engine.process(new Txn("CUR3001", new BigDecimal("700.00"), 600_000));
        // 5) Very-late txn for the 10:00 window (beyond grace) -> side output.
        engine.process(new Txn("SAV2001", new BigDecimal("999.00"), 40_000));

        log.info(() -> "Final windows = " + engine.getWindows());
        log.info(() -> "Side-output size = " + engine.getLateSideOutput().size());
    }
}

// ─── Would be in LateLogFormatter.java in a real project ───
class LateLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                record.getMessage());
    }
}
